(()=>{const GR=["АВС","КНР","МУХ","ОИД","ТЛЦ","ЕЁГ","ЗПЖ","ЧШЙ","БФЩ","ЯЮЫ","ЭЬЪ"],M=[];GR.forEach((g,i)=>{const L=[...g].join(" "),h="Insieme "+(i+1)+" · "+L;M.push({lv:1,t:"micro",n:"Impara e gioca: "+L,l:g,p:3,g:h},{lv:1,t:"game",n:"Maiuscole e minuscole",l:g,p:3,md:"case",g:h},{lv:1,t:"game",n:"Parole e lettere",l:g,p:3,md:"word",g:h},{lv:1,t:"words",n:"Completa le parole",l:g,i,g:h},{lv:1,t:"trace",n:"Traccia le lettere",l:g,g:h});if(i==3)M.push({lv:1,t:"theory",n:"La О senza accento",h:`<p>Attenzione alla <b>О</b>! Si legge «o» solo quando ha l'accento.</p><p>Senza accento diventa debole e suona come una <b>А</b>: <b>вода́</b> (acqua) si scrive con la О, ma si dice «vadà».</p><p>In russo, quindi, a volte si scrive in un modo e si legge in un altro. Facciamo un po' di pratica!</p>`,g:h},{lv:1,t:"quiz",n:"Come si pronuncia?",k:"op",g:h},{lv:1,t:"quiz",n:"О o А? Scrivi la lettera giusta",k:"oa",g:h});if([2,5,8,10].includes(i)){const a=GR.slice(i==10?9:i-2,i+1).join('');M.push({lv:1,t:"game",n:"Rinforzo: "+a.length+" lettere",l:a,p:a.length,g:"Rinforzo"})}});S.splice(1,0,...M)})();
