function trCleanSpeechText(t){return String(t||'').replace(/<[^>]*>/g,' ').replace(/&nbsp;/gi,' ').replace(/&amp;/gi,'&').replace(/&quot;/gi,'\"').replace(/&#39;|&apos;/gi,"'").replace(/&lt;/gi,'<').replace(/&gt;/gi,'>').replace(/[«»\u0301]/g,'').replace(/[-–—/]/g,' ').replace(/\s+/g,' ').trim()}
function trTextHash(text){let h=2166136261;const t=String(text||'');for(let i=0;i<t.length;i++){h^=t.charCodeAt(i);h=Math.imul(h,16777619)}return (h>>>0).toString(36)}
