function trFindPhraseAudio(text){const target=trNormAudioText(text);if(!target)return null;try{for(const key in SB_AUDIO_TEXT){if(SB_AUDIO_CLIPS&&SB_AUDIO_CLIPS[key]&&trNormAudioText(SB_AUDIO_TEXT[key])===target)return SB_AUDIO_CLIPS[key]}}catch(e){}return null}
