function trMusicSchedule(){const m=TR_SOUND;if(!m.ctx)return;trMixVolumes();if(!TR_SOUND_PREFS.music||document.hidden||app.hidden||(typeof FM_PANEL!=='undefined'&&FM_PANEL==='pause')){m.nextBeat=m.ctx.currentTime+.1;return}const beat=60/72,chords=[[45,52,55,60],[41,48,52,57],[48,55,59,64],[43,50,55,59]];while(m.nextBeat<m.ctx.currentTime+.2){const n=m.beat%16,chord=chords[Math.floor(m.beat/16)%4],at=m.nextBeat;m.chord=Math.floor(m.beat/16)%4;const hz=k=>440*Math.pow(2,(k-69)/12);if(n%4===0){for(let j=1;j<chord.length;j++)trMusicNote(hz(chord[j]),at+j*.035,beat*4,.055,'sine',(j-2)*.25);trMusicNote(hz(chord[0]),at,beat*2.8,.065,'sine',0)}if(n%2===0)trMusicNote(hz(chord[1+(n/2)%3]+12),at+.05,beat*1.5,.027,'triangle',n%4?-.22:.22);if(n===6||n===14)trMusicNote(hz(chord[3]+12),at,beat*2,.018,'sine',.3);m.nextBeat+=beat;m.beat++}}
function trChime(kind){if(kind==='wrong'){trResetStreak();trMistake()}if(!TR_SOUND_PREFS.effects)return;try{const m=trMixer();if(m.ctx.state!=='running')return;const c=m.ctx,chords=[[60,64,67],[57,60,64],[60,64,71],[55,59,62]],notes=kind==='wrong'?[55,52]:kind==='photo'?[72,79]:chords[m.chord];notes.forEach((note,i)=>{const at=c.currentTime+i*.065,o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.value=440*Math.pow(2,(note-69)/12);o.connect(g);g.connect(m.fx);g.gain.setValueAtTime(0,at);g.gain.linearRampToValueAtTime(kind==='wrong'?.10:.17,at+.008);g.gain.exponentialRampToValueAtTime(.0001,at+.55);o.start(at);o.stop(at+.57);o.onended=()=>{o.disconnect();g.disconnect()}})}catch(e){}}

function trSoundSetting(key,value){TR_SOUND_PREFS[key]=value;if(key==='visuals'){document.documentElement.dataset.trVisuals=value?'on':'off';if(!value){trClearCompanion();trJCancel()}}if(key==='visuals'&&!value)trClearRewardVisual();if(key==='praise'&&!value)trCancelReactions();try{localStorage.setItem(TR_SOUND_KEY,JSON.stringify(TR_SOUND_PREFS))}catch(e){}trMixVolumes();if(TR_SOUND.scene)trStartMusic();const label=document.getElementById('tr-'+key+'-value');if(label)label.textContent=Math.round(Number(value)*100)+'%'}
