function trSoundSettingsMarkup(){const available=typeof navigator.vibrate==='function';return '<fieldset class="tr-voice-settings tr-feedback-settings"><legend>Audio e feedback</legend><p class="tr-help">Scegli cosa sentire e quando vibrare. La pronuncia delle lezioni resta indipendente.</p>'+trFeedbackToggle('music','Musica','Sottofondo chill durante il gioco.',TR_SOUND_PREFS.music)+trFeedbackToggle('effects','Effetti sonori','Tocchi, scatti e suoni delle risposte.',TR_SOUND_PREFS.effects)+trFeedbackToggle('praise','Incoraggiamenti vocali','«Mitico!», «Bravissimo!» e complimenti di fine livello.',TR_SOUND_PREFS.praise)+trFeedbackToggle('haptics','Vibrazione',available?'Piccoli impulsi su tocchi, risposte e serie.':'Non disponibile in questo browser.',available&&TR_ARCADE_PREFS.haptics,!available)+'<button class="sm tr-action tr-quiet-button" onclick="trQuietMode()">'+trIcon('headphones')+'<span>Solo pronuncia</span></button><p class="tr-help" id="tr-feedback-status" role="status" aria-live="polite">Le scelte si salvano automaticamente.</p><details class="tr-feedback-more"><summary>Volumi e altri feedback</summary>'+['music','effects','praise'].map((key,i)=>'<div class="tr-field"><label for="tr-'+key+'Volume">'+['Volume musica','Volume effetti','Volume incoraggiamenti'][i]+' <output id="tr-'+key+'Volume-value">'+Math.round(TR_SOUND_PREFS[key+'Volume']*100)+'%</output></label><input id="tr-'+key+'Volume" type="range" min="0" max="'+(key==='music'?.5:1)+'" step="0.01" value="'+TR_SOUND_PREFS[key+'Volume']+'" oninput="trSoundSetting(\''+key+'Volume\',Number(this.value))"></div>').join('')+'<label class="tr-online"><input type="checkbox" '+(TR_SOUND_PREFS.visuals?'checked':'')+' onchange="trSoundSetting(\'visuals\',this.checked)"><span>Luci e animazioni dei successi<br><small class="tr-help">Il movimento ridotto del dispositivo viene rispettato.</small></span></label>'+trJSettingsMarkup()+'</details></fieldset>'}
