function fmLoad(){try{const s=JSON.parse(ls(FM_SAVE_KEY)||'null');if(!s||s.v!==1)return null;const f=fmBlank();f.seed=Number.isInteger(s.seed)?s.seed:f.seed;f.completed=[];for(let i=0;i<FM_ROUNDS.length&&s.completed?.[i]===i;i++)f.completed.push(i);f.index=Math.min(f.completed.length,FM_ROUNDS.length-1);f.photos=(Array.isArray(s.photos)?s.photos:[]).slice(0,f.completed.length).map((p,i)=>({id:FM_ROUNDS[i].person,word:FM_ROUNDS[i].word,quality:fcClamp(+p.quality||0,0,100),src:typeof p.src==='string'&&p.src.startsWith('data:image/jpeg;base64,')&&p.src.length<180000?p.src:''}));f.score=fcClamp(+s.score||0,0,100000);f.first=fcClamp(Math.floor(+s.first||0),0,f.completed.length);f.combo=fcClamp(+s.combo||0,0,12);f.bestCombo=fcClamp(+s.bestCombo||0,0,12);for(const[k,n]of Object.entries(s.wrong||{}))if(Number.isInteger(+k)&&+k>=0&&+k<FM_ROUNDS.length&&Number.isInteger(n)&&n>0)f.wrong[k]=Math.min(100,n);f.relax=typeof s.relax==='boolean'?s.relax:f.relax;f.finished=f.completed.length===FM_ROUNDS.length;f.registered=f.finished&&s.registered===true;return f}catch(e){return null}}
