function akScenario(s){fmLeave();st=s;AK={candidates:AK_WORDS.map((_,i)=>i),scores:AK_WORDS.map(()=>0),asked:[],question:null,guess:null,phase:'intro',mistakes:0,solved:false};AK_ACTIVE=true;document.body.classList.add('ak-active');const bar=document.getElementById('tr-topbar');if(bar)bar.hidden=true;trAudioScene(true);akRender();window.scrollTo(0,0)}
function akReset(){if(!AK)return;AK.candidates=AK_WORDS.map((_,i)=>i);AK.scores=AK_WORDS.map(()=>0);AK.asked=[];AK.question=null;AK.guess=null;AK.phase='intro';AK.mistakes=0;AK.solved=false;akRender()}
function akStart(){if(!AK_ACTIVE||!AK)return;AK.candidates=AK_WORDS.map((_,i)=>i);AK.scores=AK_WORDS.map(()=>0);AK.asked=[];AK.guess=null;AK.mistakes=0;AK.solved=false;AK.phase='question';akNextQuestion()}
function akPosterior(){const max=Math.max(...AK.candidates.map(i=>AK.scores[i])),weights=AK.candidates.map(i=>Math.exp(AK.scores[i]-max)),sum=weights.reduce((a,b)=>a+b,0);return new Map(AK.candidates.map((i,n)=>[i,weights[n]/sum]))}
function akFeature(i,key){return!!AK_WORDS[i].f[key]}
function akNextQuestion(){if(!AK_ACTIVE)return;if(!AK.candidates.length){AK.phase='mismatch';akRender();return}const rank=AK.candidates.slice().sort((a,b)=>AK.scores[b]-AK.scores[a]);if(rank.length<=1){AK.guess=rank[0];AK.phase='guess';akRender();return}const posterior=akPosterior(),opts=AK_QUESTIONS.filter(q=>!AK.asked.includes(q.key)).map(q=>{const yes=AK.candidates.reduce((sum,i)=>sum+(akFeature(i,q.key)?posterior.get(i):0),0);return{q,split:Math.abs(.5-yes)}}).sort((a,b)=>a.split-b.split);if(!opts.length){AK.guess=rank[0];AK.phase='guess';akRender();return}AK.question=opts[0].q;AK.asked.push(AK.question.key);AK.phase='question';akRender()}
const AK_RESPONSES=[{key:'yes',ru:'да',it:'sì',yes:.94,no:.06},{key:'no',ru:'нет',it:'no',yes:.06,no:.94},{key:'possible',ru:'возможно',it:'può essere',yes:.68,no:.32},{key:'impossible',ru:'невозможно',it:'impossibile',yes:.02,no:.98},{key:'unknown',ru:'не знаю',it:'non lo so',yes:.5,no:.5}];
function akAnswer(key){if(!AK_ACTIVE||AK.phase!=='question'||!AK.question)return;const answer=AK_RESPONSES.find(a=>a.key===key);if(!answer)return;const q=AK.question;say(answer.ru);for(const i of AK.candidates)AK.scores[i]+=Math.log(akFeature(i,q.key)?answer.yes:answer.no);AK.question=null;akNextQuestion()}
function akGuess(answer){if(!AK_ACTIVE||AK.phase!=='guess'||AK.guess==null)return;if(answer){say('верно');AK.solved=true;AK.phase='result';akRegister();akRender();return}say('неправильно');AK.mistakes++;AK.candidates=AK.candidates.filter(i=>i!==AK.guess);AK.guess=null;if(!AK.candidates.length){AK.phase='mismatch';akRender();return}AK.question=null;AK.phase='question';akNextQuestion()}
function akRegister(){if(!AK||AK.registered)return;AK.registered=true;const errors=AK.mistakes+(AK.solved?0:2);prog(0,errors);if(AK.solved)trLevelReaction(errors,false)}
function akWordMarkup(w){return '<span class="ak-word"><b lang="ru">'+w.ru+'</b><span>'+w.it+'</span></span>'}
function akGenieMark(small=false){const grad=small?'akLampGoldMini':'akLampGoldMain';return '<span class="ak-genie-wrap '+(small?'ak-small':'')+'">'+trMascot('matryoshka',0,'ak-genie-doll')+'<svg class="ak-genie-lamp" viewBox="0 0 180 105" aria-hidden="true"><defs><linearGradient id="'+grad+'" x1="0" y1="0" x2=".8" y2="1"><stop stop-color="#fff4bd"/><stop offset=".26" stop-color="#e9b448"/><stop offset=".62" stop-color="#bc7428"/><stop offset="1" stop-color="#75451f"/></linearGradient></defs><ellipse cx="91" cy="96" rx="59" ry="6" fill="#21375f" opacity=".16"/><path d="M126 48c27-20 49-14 45 1-3 12-13 17-27 15" fill="none" stroke="url(#'+grad+')" stroke-width="9" stroke-linecap="round"/><path d="M57 60 20 48c-9-3-15 3-8 9l39 21 17-8z" fill="url(#'+grad+')" stroke="#805020" stroke-width="3" stroke-linejoin="round"/><path d="M130 61c4-19 18-22 21-12 3 8-2 14-12 17" fill="none" stroke="#f7d77a" stroke-width="3" stroke-linecap="round"/><path d="M49 61c3-17 20-28 43-28 26 0 43 12 46 31l-8 18c-6 12-19 18-39 18-22 0-37-8-44-23l-2-16z" fill="url(#'+grad+')" stroke="#805020" stroke-width="3"/><path d="M52 73c18 10 58 12 82 0" fill="none" stroke="#2f58a0" stroke-width="7"/><path d="M61 85c13 7 42 8 59 0" fill="none" stroke="#f6d274" stroke-width="3" stroke-linecap="round"/><path d="M57 58c15-10 50-12 69-1" fill="none" stroke="#fff0ad" stroke-width="3" stroke-linecap="round"/><path d="M72 31c8-7 29-8 39 0l-3 7H75z" fill="url(#'+grad+')" stroke="#805020" stroke-width="2.5"/><path d="M84 27h15m-7-7v8" stroke="#fff0ad" stroke-width="2.5" stroke-linecap="round"/><circle cx="94" cy="75" r="5" fill="#f9e8ad" stroke="#805020" stroke-width="1.5"/><circle cx="94" cy="75" r="2" fill="#c33140"/><path d="M65 93h56" stroke="#805020" stroke-width="3" stroke-linecap="round"/></svg><i class="ak-genie-spark one">✦</i><i class="ak-genie-spark two">✧</i><i class="ak-genie-spark three">✦</i></span>'}
function akRender(){if(!AK_ACTIVE||!AK)return;const app=document.getElementById('app'),top='<header class="ak-top"><div class="ak-brand">'+akGenieMark(true)+'<span>GENIO DEL LESSICO<small>Il tuo piccolo Akinator russo</small></span></div><button class="ak-back" onclick="akHome()">‹ Mappa</button></header>',hero='<div class="ak-hero">'+akGenieMark()+'<div><p class="ak-kicker">Arcade · Risposte</p><h1>Il genio delle parole</h1><p class="ak-sub">Tu pensa a una parola. Io provo a indovinarla con le tue risposte.</p></div></div>';let body='';
if(AK.phase==='intro'){body='<section class="ak-panel">'+hero+'<p class="ak-sub">Pensa in segreto a una parola del livello «Parole che già conosci». Non selezionarla sullo schermo e tienila a mente: il genio proverà a indovinarla dalle tue risposte.</p><h2 class="ak-section-title">Hai pensato alla parola?</h2><div class="ak-actions"><button class="pr" onclick="akStart()">Sì, inizia!</button></div><p class="ak-notice">Le domande sono in italiano. Per rispondere puoi usare <b lang="ru">да</b> (sì), <b lang="ru">нет</b> (no), <b lang="ru">возможно</b> (può essere), <b lang="ru">невозможно</b> (impossibile) e <b lang="ru">не знаю</b> (non lo so).</p></section>'}
else if(AK.phase==='question'){const pos=AK.candidates.length,step=AK.asked.length,choices=AK_RESPONSES.map(a=>'<button class="ak-answer" onclick="akAnswer(\''+a.key+'\')"><b lang="ru">'+a.ru+'</b><span>'+a.it+'</span></button>').join('');body='<section class="ak-panel">'+hero+'<div class="ak-progress"><i style="--ak-progress:'+Math.min(100,step/AK_QUESTIONS.length*100)+'%"></i></div><div class="ak-question"><span class="ak-step">Domanda '+step+' · '+pos+' parole possibili</span><h2>'+AK.question.q+'</h2><p class="ak-sub">Scegli la risposta più vicina a quello che pensi; se non sei sicura, puoi dire “può essere” o “non lo so”.</p><div class="ak-answer-grid ak-confidence-grid">'+choices+'</div></div></section>'}
else if(AK.phase==='guess'){const w=AK_WORDS[AK.guess];body='<section class="ak-panel">'+hero+'<div class="ak-question"><span class="ak-step">La mia ipotesi · '+(AK.asked.length)+' domande</span><h2>Sto pensando a…</h2><div class="ak-guess-word" lang="ru">'+w.ru+'</div><div class="ak-guess-translation">'+w.it+'</div><p>Ci ho preso?</p><div class="ak-answer-grid"><button class="ak-answer" onclick="akGuess(true)"><b lang="ru">верно</b><span>esatto, hai indovinato</span></button><button class="ak-answer" onclick="akGuess(false)"><b lang="ru">неправильно</b><span>no, riprova</span></button></div></div></section>'}
else if(AK.phase==='mismatch'){body='<section class="ak-panel ak-result">'+hero+'<h2>Non ho indovinato questa volta</h2><p>Forse la parola non è tra quelle che conosco ancora. Pensa a una parola del lessico base e riproviamo.</p><div class="ak-actions"><button class="pr" onclick="akReset()">Riprova con una nuova parola</button><button class="sm" onclick="akHome()">Torna alla mappa</button></div></section>'}
else{const target=AK_WORDS[AK.guess],n=AK.asked.length,score=Math.max(40,220-n*18-AK.mistakes*25);body='<section class="ak-panel ak-result">'+hero+'<p class="ak-kicker">Хорошо!</p><h2>Il genio ti ha indovinata!</h2><div class="ak-result-word"><span lang="ru">'+target.ru+'</span></div><p>'+target.it+' · '+n+' domande · '+score+' punti</p><div class="ak-actions"><button class="pr" onclick="next()">Continua il percorso</button><button class="sm" onclick="akReset()">Nuova parola</button></div></section>'}
app.innerHTML='<main class="ak-shell">'+top+body+'</main>'}
function scenario(s){if(s.akinatorFinal){akScenario(s);return}fmLeave();st=s;FM=fmLoad()||fmBlank();FM_ACTIVE=true;for(const i of [1,2])document.documentElement.style.setProperty('--fc-sprite-'+i,'url("'+FC_ART.images[i]+'")');FM_PANEL=null;FC.introDismissed=false;FC.guideReturn=null;FM_STATE=FM.finished?'result':'intro';FC.clock=0;FC.panX=FC.panY=0;FC.zoom=1;document.body.classList.add('fm-active');document.getElementById('tr-topbar').hidden=true;trAudioScene(true);fmRender();fmEnsureArt();fmWarmRound();if(FM.finished&&!FM.registered)fmFinish();window.scrollTo(0,0)}
function fmIcon(kind){const names={back:'chevron-left',sound:'volume-2',camera:'camera',pause:'pause',play:'play',check:'check',album:'images',minus:'minus',plus:'plus'};return trIcon(names[kind]||'camera')}
function fmHeader(){return '<header class="fc-header"><button class="fc-icon" onclick="home()" aria-label="Torna alla mappa">'+fmIcon('back')+'</button><div><b>Famiglia e persone</b><span>Obiettivo: famiglia</span></div><button class="fc-icon" onclick="fmPause()" aria-label="Pausa e impostazioni">'+fmIcon('pause')+'</button></header>'}
function fmStage(){return Math.min(2,Math.floor(FM.index/4))}
function fmStageName(){return ['La passeggiata','Passo svelto','Vicini e lontani'][fmStage()]}
function fmCaption(){const q=FM_ROUNDS[FM.index];return FM.index===6||FM.index===7?'La famiglia di Maksim':FM.index===8||FM.index===9?'Gli amici di Anja':'La famiglia di Anja'}
function fmTarget(){const q=FM_ROUNDS[FM.index];if(FM_STATE==='intro')return '<section class="fc-target fc-intro-title"><div><h1>Obiettivo: famiglia</h1><p>Un album. Quattordici scatti da conquistare.</p></div></section>';return '<section class="fc-target"><button class="fc-target-word" onclick="fmHear()" aria-label="Riascolta '+q.word+'">'+fmIcon('sound')+'<span lang="ru">'+q.word+'</span></button><div><span>'+fmCaption()+'</span><b>'+fmStageName()+'</b></div></section>'}
function fmProgress(){return '<div class="fc-progress" role="progressbar" aria-label="Scatti nell’album" aria-valuenow="'+FM.completed.length+'" aria-valuemin="0" aria-valuemax="'+FM_ROUNDS.length+'">'+FM_ROUNDS.map((_,i)=>'<i class="'+(i<FM.completed.length?'done':i===FM.index?'current':'')+'"></i>').join('')+'<span>'+FM.completed.length+'/'+FM_ROUNDS.length+'</span></div>'}
function fmIntro(){if(FC.introDismissed)return '';return '<section class="fc-intro-panel fc-entry-card" aria-labelledby="fc-rules-title"><header class="fc-panel-head"><h2 id="fc-rules-title">Un album, quattordici scatti.</h2><button class="fc-icon" onclick="fmDismissIntro()" aria-label="Chiudi le regole e guarda la scena">'+trIcon('x')+'</button></header><div class="fc-panel-body fc-rules-body" tabindex="0"><p>Ascolta la parola russa e fotografa <b>la persona giusta</b>.</p><ol><li><b>Scegli chi seguire.</b> Tocca una persona: il contorno e il nome mostrano chi hai selezionato.</li><li><b>Segui il passaggio.</b> Trascina la scena per tenere la persona nel mirino. Lo zoom è facoltativo: usalo per comporre la foto.</li><li><b>Controlla il nome e scatta.</b> Il contorno mostra chi fotografi. Quando leggi “pronto!”, premi il pulsante rosso.</li></ol><p class="fc-rule-note">Hai 5 foto per rullino e la ricarica è automatica. Un’inquadratura da aggiustare non consuma foto e non interrompe la serie. L’errore conta solo se fotografi un’altra persona. I passaggi accelerano e cambiano distanza, senza coprirsi.</p></div><footer class="fc-panel-actions">'+fmStartButton()+'<button class="sm" onclick="fmGuideOpen()">'+fmIcon('album')+' Chi è chi? · Conosci la famiglia</button></footer></section>'}
function fmControls(){if(FM_STATE==='intro')return '<div class="fc-controls fc-intro-controls">'+(FC.introDismissed&&!FM_PANEL?fmStartButton():'')+'<p class="fc-entry-hint">'+(FC.introDismissed?'Inizia quando vuoi: il primo nome russo ti dirà chi cercare.':'Puoi riprovare ogni scatto. L’album si completa una foto alla volta.')+'</p></div>';return '<div class="fc-controls"><div class="fc-zoom"><button class="fc-icon" onclick="fmZoom(-.1)" aria-label="Riduci lo zoom">'+fmIcon('minus')+'</button><label for="fc-zoom">Zoom</label><input id="fc-zoom" type="range" min="0.9" max="1.75" step="0.05" value="'+FC.zoom+'" oninput="fmSetZoom(this.value)" aria-label="Zoom dell’obiettivo"><button class="fc-icon" onclick="fmZoom(.1)" aria-label="Aumenta lo zoom">'+fmIcon('plus')+'</button><output id="fc-zoom-label">'+FC.zoom.toFixed(1)+'×</output></div><div class="fc-thumb-controls"><button class="fc-side" onclick="fmHear(.8)">'+fmIcon('sound')+'<span>Più lento</span></button><button class="fc-shutter" id="fc-shutter" onpointerdown="fmPressShutter(event)" onclick="fmShutterClick(event)" aria-label="Scatta la foto">'+fmIcon('camera')+'<span>Scatta</span></button><button class="fc-side" onclick="fmGuideOpen()">'+fmIcon('album')+'<span>Chi è chi?</span></button></div></div>'}
function fmRender(){if(!FM_ACTIVE)return;fmStopLoop();FC.lastAmmo=-1;FC.lastFocus='';if(FM_STATE==='result'){app.innerHTML='<main class="fm-game fc-result">'+fmHeader()+fmResult()+'</main>';trMixVolumes();return}app.innerHTML='<main class="fm-game fc-game">'+fmHeader()+fmProgress()+fmTarget()+'<div class="fc-view" id="fc-view"><canvas id="fc-scene" tabindex="0" role="img" aria-label="Persone in movimento in un villaggio russo. Trascina per mirare; con la tastiera usa le frecce e spazio per scattare." onpointerdown="fmPointerDown(event)" onpointermove="fmPointerMove(event)" onpointerup="fmPointerUp(event)" onpointercancel="fmPointerUp(event)" onkeydown="fmKey(event)"></canvas><div class="fc-vignette" aria-hidden="true"></div><div class="fc-reticle" id="fc-reticle" aria-hidden="true"><i></i><i></i><i></i><i></i><span></span></div><div class="fc-view-hud"><span id="fc-points">'+FM.score+' pt</span><button class="fc-auto" id="fc-auto" onclick="fmAutoFocus()" hidden>Fuoco auto</button><span class="fc-film" id="fc-film" aria-label="Scatti nel rullino"></span></div><div class="fc-focus" id="fc-focus">Trascina per mirare</div><div class="fc-flash" id="fc-flash" aria-hidden="true"></div><div class="fc-overlay" id="fc-overlay">'+(FM_STATE==='intro'?fmIntro():FM_STATE==='capture'?fmCaptureCard():'')+'</div></div>'+fmControls()+'<div class="fc-message" id="fc-message" role="status">'+(FM_STATE==='intro'?'Dodici parole · tre prove di abilità':FM_STATE==='capture'?'Scatto salvato nel tuo album.':'Il contorno e il nome mostrano chi stai fotografando.')+'</div></main>';if(FM_PANEL)fmRenderPanel();if(FC.ready)fmStartLoop();trMixVolumes()}
function fmResize(){const view=document.getElementById('fc-view');if(!view||!FC.canvas)return;FC.rect=view.getBoundingClientRect();FC.w=Math.max(1,FC.rect.width);FC.h=Math.max(1,FC.rect.height);FC.dpr=Math.min(1.5,devicePixelRatio||1);const width=Math.round(FC.w*FC.dpr),height=Math.round(FC.h*FC.dpr);if(FC.canvas.width!==width||FC.canvas.height!==height){FC.canvas.width=width;FC.canvas.height=height}FC.ctx=FC.canvas.getContext('2d',{alpha:false});fmDrawScene()}
/* PERF: a running RAF owns camera drawing. Input changes state immediately;
   pointermove/slider bursts never paint the same scene repeatedly between frames.
   fmShoot/fmPhoto/fmDrawScene remain synchronous for exact capture and hit tests. */
function fmRequestDraw(){if(!FC.raf)fmDrawScene()}
function fmStartLoop(){fmStopLoop();FC.canvas=document.getElementById('fc-scene');if(!FC.canvas)return;fmResize();FC.resize=new ResizeObserver(fmResize);FC.resize.observe(document.getElementById('fc-view'));FC.last=performance.now();fmUpdateHud();const tick=now=>{FC.raf=0;if(!FM_ACTIVE||FM_STATE==='result'||document.hidden||app.hidden||FM_PANEL||(FM_STATE!=='playing'&&FM_STATE!=='intro'))return;const dt=Math.min(.05,Math.max(0,(now-FC.last)/1000));FC.last=now;FC.clock+=dt;fmUpdateHud(fmDrawScene());FC.raf=requestAnimationFrame(tick)};if(!document.hidden&&!app.hidden&&!FM_PANEL&&(FM_STATE==='playing'||FM_STATE==='intro'))FC.raf=requestAnimationFrame(tick)}
function fmSway(){if(FM?.relax||FM_STATE==='intro')return {x:0,y:0};const level=fmStage(),t=FC.clock;return{x:Math.sin(t*(1.03+level*.23))*(.009+level*.012)+Math.sin(t*.47+.6)*.002,y:Math.sin(t*(1.29+level*.31)+1)*(.005+level*.006)}}

function fmProjectActors(){const w=FC.w,h=FC.h,sway=fmSway();return fmActorSpecs().map((a,i)=>{const travel=((FC.clock*a.speed+a.phase)%a.period)-a.edge,x=a.dir===1?travel:1-travel,child=a.id==='artem'||a.id==='masha',height=(a.lane===1?.31:.49)*(child?.82:1),feet=a.lane===1?.65:.80,z=FC.zoom,cadence=fcClamp(a.speed*w/Math.max(1,height*h*.42),FM.relax?.4:.52,1.5),gait=(FC.clock*cadence+i*.173)%1,compress=1-.012*(.5-.5*Math.cos(gait*Math.PI*4)),dh=height*h*z*compress,hip=Math.sin(gait*Math.PI*2)*dh*.004,cx=((x-.5)*z+.5+FC.panX+sway.x)*w+hip,ground=(feet-.5)*z*h+h*.5+(FC.panY+sway.y)*h,frames=FC_ART.people[a.id].frames.length;return{...a,cx,cy:ground-dh/2,h:dh,ground,frame:Math.floor(gait*frames)%frames,gait,cadence,scale:dh/h}}).sort((a,b)=>a.lane===b.lane?a.ground-b.ground:b.lane-a.lane)}
function fmDrawScene(showFocus=true,frameActors=null){if(!FC.ready||!FC.ctx||!FC.w)return;const c=FC.ctx,w=FC.w,h=FC.h,actors=frameActors||fmProjectActors(),focused=showFocus&&FM_STATE==='playing'?fmFocus(undefined,actors):null;c.setTransform(FC.dpr,0,0,FC.dpr,0,0);c.fillStyle='#dae8ee';c.fillRect(0,0,w,h);const bg=FC.images[0],background=fmBackgroundRect();c.drawImage(bg,background.x,background.y,background.w,background.h);FC.visible=actors;for(const a of FC.visible){if(a.cx<-w*.4||a.cx>w*1.4)continue;const sprite=FC_ART.people[a.id],f=sprite.frames[a.frame],img=FC.images[sprite.image],dw=a.h*f.w/f.h,dy=a.ground-a.h;c.save();c.globalAlpha=.17;c.fillStyle='#294756';c.beginPath();c.ellipse(a.cx,a.ground+2,dw*.37,Math.max(3,a.h*.025),0,0,Math.PI*2);c.fill();c.globalAlpha=1;c.translate(a.cx,dy);if(a.dir<0)c.scale(-1,1);c.drawImage(img,f.x,f.y,f.w,f.h,-dw/2,0,dw,a.h);c.restore();if(showFocus&&FM_STATE==='playing'&&a.cx>0&&a.cx<w){c.font='600 '+Math.max(10,Math.min(12,w*.032))+'px system-ui';c.textAlign='center';const name=FC_PEOPLE[a.id].n,tw=c.measureText(name).width;c.fillStyle=a.id===focused?.a?.id?'#1f4e9c':'rgba(255,255,255,.91)';c.beginPath();c.roundRect(a.cx-tw/2-6,a.ground+4,tw+12,19,5);c.fill();c.fillStyle=a.id===focused?.a?.id?'#fff':'#14224a';c.fillText(name,a.cx,a.ground+18)}}if(focused)fmDrawFocus(c,focused);FC.frame++;if(showFocus)FC.shotFrame={focus:focused||{ready:false,text:'Tocca una persona o portala nel mirino.'},actors,clock:FC.clock,index:FM.index,w,h,panX:FC.panX,panY:FC.panY,zoom:FC.zoom,manualId:FC.manualId};return focused||{ready:false}}
function fmUpdateHud(focus){if(!FM_ACTIVE||FM_STATE==='result')return;focus=focus||fmFocus();const el=document.getElementById('fc-focus'),reticle=document.getElementById('fc-reticle'),shutter=document.getElementById('fc-shutter');if(el){el.dataset.ready=String(FM_STATE==='playing'&&focus.ready);const text=FM_STATE==='intro'?'Trascina la scena con un dito':FM_STATE==='capture'?'Un ricordo conquistato':FC.reloadUntil>FC.clock?'Cambio rullino…':focus.text;if(text!==FC.lastFocus){el.textContent=text;FC.lastFocus=text}}reticle?.classList.toggle('ready',FM_STATE==='playing'&&focus.ready);if(shutter){shutter.dataset.ready=String(!!focus.ready);const disabled=FM_STATE!=='playing'||!!FM_PANEL||FC.coolUntil>FC.clock||FC.reloadUntil>FC.clock;if(shutter.disabled!==disabled)shutter.disabled=disabled}const reset=document.getElementById('fc-auto');if(reset&&reset.hidden!==!FC.manualId)reset.hidden=!FC.manualId;const ammo=document.getElementById('fc-film');if(ammo&&FC.lastAmmo!==(FM.ammo??5)){FC.lastAmmo=FM.ammo??5;ammo.innerHTML=Array.from({length:5},(_,i)=>'<i class="'+(i<(FM.ammo??5)?'loaded':'')+'"></i>').join('')}if(FC.reloadUntil&&FC.clock>=FC.reloadUntil){FM.ammo=5;FC.reloadUntil=0;fmMessage('Rullino pronto. Cerca il prossimo passaggio.')}if(FC.toastUntil&&FC.clock>FC.toastUntil){FC.toastUntil=0;fmMessage('Segui il contorno · controlla il nome · scatta quando è pronto.',false)}}
function fmResetCamera(){FC.introDismissed=false;FC.guideReturn=null;fmClearFocus();FC.clock=0;FC.panX=FC.panY=0;FC.zoom=1;FC.coolUntil=FC.reloadUntil=FC.toastUntil=0;FC.lastFocus='';FC.lastAmmo=-1;FM.ammo=5}
function fmStart(){if(!FC.ready){fmEnsureArt();return}if(FM.finished)FM=fmBlank();fmResetCamera();FM_STATE='playing';FM_PANEL=null;fmRender();fmSave();fmWarmRound();fmHear();document.getElementById('fc-scene')?.focus({preventScroll:true})}
function fmHear(pace){if(!FM_ACTIVE||FM_STATE==='result')return;fmSpeakRound(FM_STATE==='capture',pace)}
function fmVoiceGender(full){const person=FM_ROUNDS[FM.index].person;if(full)return ['sergej','pavel','maxim','artem','dima','dyadya'].includes(person)?'male':'female';return ['sergej','pavel','maxim','artem','dima','dyadya'].includes(person)?'male':'female'}
function fmSpeakRound(full,pace){const q=FM_ROUNDS[FM.index];return trTtsSpeakItems([{text:full?q.phrase:q.word,lang:'ru-RU',gender:fmVoiceGender(full)}],null,null,{pace})}
function fmWarmRound(){if(!FM)return;const q=FM_ROUNDS[FM.index];for(const [text,full]of [[q.word,false],[q.phrase,true]])for(const clip of trNeuralSource(text,trCastId('ru-RU',fmVoiceGender(full)))){trDecodeClip(clip).catch(()=>{});trDecodeClip(trLearningClip(clip,.8)).catch(()=>{})}}
function fmSetZoom(n){FC.zoom=fcClamp(+n||1,.9,1.75);const input=document.getElementById('fc-zoom'),label=document.getElementById('fc-zoom-label');if(input)input.value=FC.zoom;if(label&&label.textContent!==FC.zoom.toFixed(1)+'×')label.textContent=FC.zoom.toFixed(1)+'×';fmRequestDraw()}
function fmZoom(delta){if(FM_PANEL||FM_STATE!=='playing')return;fmSetZoom(Math.round((FC.zoom+delta)*20)/20)}
function fmKey(e){if(FM_STATE!=='playing'||FM_PANEL)return;const moves={ArrowLeft:[-.035,0],ArrowRight:[.035,0],ArrowUp:[0,-.035],ArrowDown:[0,.035]};if(moves[e.key]){e.preventDefault();FC.panX=fcClamp(FC.panX+moves[e.key][0],-FC_MOTION.panX,FC_MOTION.panX);FC.panY=fcClamp(FC.panY+moves[e.key][1],-FC_MOTION.panY,FC_MOTION.panY);fmDrawScene()}else if(e.code==='Space'||e.key==='Enter'){e.preventDefault();fmShoot()}else if(e.key==='+'||e.key==='=')fmZoom(.1);else if(e.key==='-')fmZoom(-.1)}
function fmMessage(text,timed=true){const el=document.getElementById('fc-message');if(el)el.textContent=text;FC.toastUntil=timed?FC.clock+3:0}
function fmPhoto(shot=FC.shotFrame){fmDrawScene(false,shot?.actors);const c=document.createElement('canvas');c.width=216;c.height=244;const crop=fmCrop();c.getContext('2d').drawImage(FC.canvas,crop.x*FC.dpr,crop.y*FC.dpr,crop.w*FC.dpr,crop.h*FC.dpr,0,0,216,244);const src=c.toDataURL('image/jpeg',.74);fmDrawScene();return src}

function fmCaptureCard(){const photo=FM.photos[FM.index],q=FM_ROUNDS[FM.index];return '<section class="fc-capture" role="status"><div class="fc-polaroid"><img src="'+photo.src+'" alt="La foto di '+FC_PEOPLE[q.person].n+' appena scattata"><b>'+FC_PEOPLE[q.person].n+'</b></div><div><h2>Scatto riuscito!</h2><p lang="ru">'+q.phrase+'</p><small>Inquadratura '+photo.quality+'%'+(FM.combo>1?' · '+FM.combo+' scatti puliti di fila':'')+'</small></div><button class="pr" onclick="fmNext()">'+(FM.index===FM_ROUNDS.length-1?'Apri il tuo album':'Prossimo scatto')+'</button></section>'}
function fmNext(){if(FM_STATE!=='capture')return;stopT();if(FM.index===FM_ROUNDS.length-1){fmFinish();return}FM.index++;FM_STATE='playing';fmResetCamera();fmSave();fmRender();fmWarmRound();fmHear();if(FM.index===4)fmMessage('Ora il passo accelera e la camera oscilla. Segui le persone con il dito.');if(FM.index===8)fmMessage('Vicini e lontani: anche le persone sul fondo valgono. Usa lo zoom solo se vuoi avvicinare la foto.')}
function fmFinish(){if(FM.completed.length!==FM_ROUNDS.length)return;const firstFinish=!FM.finished;FM.finished=true;FM_STATE='result';FM_PANEL=null;if(!FM.registered){prog(0,Object.keys(FM.wrong).length);FM.registered=true}fmSave();fmRender();if(firstFinish){trLevelReaction(Object.keys(FM.wrong).length,true)}window.scrollTo(0,0)}
function fmResult(){const mistakes=Object.keys(FM.wrong).length,stars=mistakes===0?3:mistakes<=2?2:1;return '<section class="fc-result-heading"><h1>La passeggiata è nel tuo album.</h1><p>'+FM_ROUNDS.length+' parole russe, '+FM_ROUNDS.length+' ricordi conquistati.</p>'+trStarMarkup(stars)+'<b>'+FM.score+' punti · serie migliore '+FM.bestCombo+'</b></section><div class="fc-album">'+FM_ROUNDS.map((q,i)=>{const p=FM.photos[i];return '<figure>'+(p?.src?'<img src="'+p.src+'" alt="Foto di '+FC_PEOPLE[q.person].n+'">':fmPortrait(q.person))+'<figcaption><b lang="ru">'+q.word+'</b><span>'+FC_PEOPLE[q.person].n+'</span></figcaption></figure>'}).join('')+'</div><div class="fc-result-actions"><button class="pr" onclick="fmContinueCourse()">Continua il percorso</button><button class="sm" onclick="fmRestart()">Un altro servizio fotografico</button></div>'}
function fmContinueCourse(){if(!FM_ACTIVE||!FM.finished)return;fmLeave();next()}
function fmRestart(){FM=fmBlank();FM_STATE='intro';FM_PANEL=null;fmResetCamera();fmSave();fmRender()}
function fmPortrait(id){const s=FC_ART.people[id],img='var(--fc-sprite-'+s.image+')';return '<span class="fc-portrait" style="--portrait:'+img+';--ps:'+s.portrait.size+';--px:'+s.portrait.x+'%;--py:'+s.portrait.y+'%" aria-hidden="true"></span>'}
function fmPause(){if(!FM_ACTIVE)return;if(FM_STATE==='result'){trOpenSettings(document.activeElement);return}FM_PANEL='pause';stopT();fmSave();fmRender();trMixVolumes()}
function fmGuideOpen(){FC.guideReturn=FM_PANEL==='pause'?'pause':null;FM_PANEL='guide';stopT();fmRender();trMixVolumes()}
function fmRenderPanel(){const el=document.getElementById('fc-overlay');if(!el)return;document.querySelectorAll('.fc-header,.fc-progress,.fc-target,.fc-controls,.fc-message,#fc-scene').forEach(node=>{node.inert=true;node.setAttribute('aria-hidden','true')});if(FM_PANEL==='guide'){const intro=FM_STATE==='intro';el.innerHTML='<section class="fc-panel fc-guide" role="dialog" aria-modal="true" aria-labelledby="fc-guide-title"><header class="fc-panel-head"><h2 id="fc-guide-title">La famiglia di Anja</h2><button class="fc-icon" data-fc-close onclick="fmGuideClose()" aria-label="Chiudi Chi è chi">'+trIcon('x')+'</button></header><div class="fc-panel-body" tabindex="0"><p>Dodici persone, quattordici parole per il tuo album. Artëm e Maša sono i figli di Maksim, il fratello di Anja.</p><p>Sentirai anche <span lang="ru">мать</span> (madre) e <span lang="ru">отец</span> (padre).</p><div class="fc-cast">'+FC_IDS.map(id=>{const p=FC_PEOPLE[id];return '<div>'+fmPortrait(id)+'<b>'+p.n+'</b><span lang="ru">'+p.ru+'</span><small>'+p.role+'</small></div>'}).join('')+'</div></div><footer class="fc-panel-actions">'+(intro?fmStartButton():'')+'<button class="'+(intro?'sm':'pr')+'" onclick="fmGuideClose()">'+(intro?'Torna alle regole':'Torna all’obiettivo')+'</button></footer></section>'}else el.innerHTML='<section class="fc-panel fc-pause" role="dialog" aria-modal="true" aria-labelledby="fc-pause-title"><header class="fc-panel-head"><h2 id="fc-pause-title">Una pausa dietro l’obiettivo</h2><button class="fc-icon" data-fc-close onclick="fmResume()" aria-label="Chiudi la pausa">'+trIcon('x')+'</button></header><div class="fc-panel-body"><p>Ascolta chi cercare, tocca la persona e seguila trascinando la scena. Contorno e nome mostrano chi fotografi: quando leggi “pronto!”, scatta. Lo zoom è facoltativo. Se devi aggiustare l’inquadratura, non perdi foto né serie.</p><label><input type="checkbox" '+(FM.relax?'checked':'')+' onchange="FM.relax=this.checked;fmSave()"> Movimento delicato</label><div class="fc-pause-options"><button class="sm" onclick="fmGuideOpen()">Chi è chi?</button><button class="sm" onclick="fmOpenAudio()">Voci e musica</button><button class="sm" onclick="home()">Salva e torna alla mappa</button></div></div><footer class="fc-panel-actions"><button class="pr" onclick="fmResume()">Riprendi</button></footer></section>';requestAnimationFrame(()=>{if(FM_PANEL)el.querySelector('[data-fc-close]')?.focus({preventScroll:true})})}
function fmResume(){FM_PANEL=null;FC.touches.clear();FC.drag=FC.pinch=null;fmRender();if(FM_STATE==='playing')fmHear();trMixVolumes()}
function fmOpenAudio(){FM_PANEL='pause';fmSave();fmRender();trOpenSettings(document.activeElement)}
document.addEventListener('visibilitychange',()=>{if(!FM_ACTIVE)return;if(document.hidden){cancelAnimationFrame(FC.raf);FC.raf=0;FC.touches.clear();FC.drag=FC.pinch=null}else{FC.last=performance.now();if(!FC.raf)fmStartLoop()}});

/* CAMERA FAIRNESS CONTRACT v1.10.5
 * The word is the learning test; zoom and pixel-perfect composition are not.
 * 1. One convoy, equal speed, maximum-pose-width spacing: no hidden subjects.
 * 2. A manual selection stays on that person until the player changes it.
 * 3. The shutter consumes the painted frame, including its subject and crop.
 * 4. Framing help is free; only a valid photo of the wrong person loses a try.
 * Keep the approved eight-frame artwork/animation, recordings and save keys.
 */
function fmActorSpecs(){
 const target=FM_ROUNDS[FM.index].person,stage=fmStage(),rest=FC_IDS.filter(id=>id!==target);
 const offset=(FM.seed+FM.index*7)%rest.length;
 const ids=[target,rest[offset],rest[(offset+3)%rest.length],rest[(offset+6)%rest.length]];
 const specs=ids.map((id,i)=>({id,target:i===0,lane:stage===2?(i===0?FM.index%2:i%2):stage===1?i%2:0,dir:FM.index%2?-1:1}));
 // Work in scene coordinates, before zoom/pan. Include the WIDEST animation
 // pose, both lanes and children's height; camera transforms preserve gaps.
 const ratio=FC.w>0?FC.h/FC.w:1.3;
 const width=Math.max(...specs.map(a=>{
  const height=(a.lane===1?.31:.49)*(['artem','masha'].includes(a.id)?.82:1);
  return height*ratio*Math.max(...FC_ART.people[a.id].frames.map(f=>f.w/f.h));
 }));
 const gap=Math.max(.72,width+.16),period=gap*specs.length,edge=(period-1)/2;
 return specs.map((a,i)=>({...a,phase:edge-.35+i*gap,period,edge,speed:(.17+stage*.045)*(FM.relax?.72:1)}));
}
function fmFocus(forcedId,actors=fmProjectActors()){
 const w=FC.w,h=FC.h,crop=fmCrop(),selected=forcedId||FC.manualId;
 let a=selected?actors.find(person=>person.id===selected):null;
 if(selected&&!a)return {ready:false,reason:'empty',text:'La persona scelta non è nella scena. Tocca chi vuoi seguire.'};
 if(!selected){
  const candidates=actors.filter(person=>{
   const b=fmActorBounds(person);
   return b.x+b.w>crop.x&&b.x<crop.x+crop.w&&b.y+b.h>crop.y&&b.y<crop.y+crop.h;
  }).map(person=>({...person,distance:Math.hypot((person.cx-w*.5)/(crop.w*.5),(person.cy-h*.52)/(crop.h*.5))})).sort((a,b)=>a.distance-b.distance);
  const current=candidates.find(person=>person.id===FC.focusId),best=candidates[0];
  a=current&&(!best||current.distance<=best.distance+.18)?current:best;
 }
 FC.focusId=a?.id||selected||null;
 if(!a)return {ready:false,reason:'empty',text:'Tocca una persona o portala nel mirino.'};
 const b=fmActorBounds(a),name=FC_PEOPLE[a.id].n,margin=Math.max(3,Math.min(w,h)*.025);
 const dx=Math.abs(a.cx-(crop.x+crop.w/2))/(crop.w/2),dy=Math.abs(a.cy-(crop.y+crop.h/2))/(crop.h/2),size=a.h/crop.h;
 a={...a,dx,dy,size};
 // No minimum size or invisible central sweet spot. The entire silhouette
 // fitting the actual photo is sufficient, with a small edge tolerance.
 const fits=b.x>=crop.x-margin&&b.y>=crop.y-margin&&b.x+b.w<=crop.x+crop.w+margin&&b.y+b.h<=crop.y+crop.h+margin;
 if(!fits){
  const large=b.w>crop.w+margin*2||b.h>crop.h+margin*2;
  return {ready:false,reason:large?'large':'off',a,text:name+(large?' · riduci un po’ lo zoom':' · porta la sagoma nel mirino')};
 }
 const quality=Math.round(fcClamp(100-(dx+dy)*18-Math.abs(size-.76)*25,50,100));
 return {ready:true,a,quality,text:name+' · pronto! Scatta'};
}
function fmShotSnapshot(){
 const shot=FC.shotFrame;
 if(!shot||shot.index!==FM.index||shot.w!==FC.w||shot.h!==FC.h||shot.panX!==FC.panX||shot.panY!==FC.panY||shot.zoom!==FC.zoom||shot.manualId!==FC.manualId||shot.clock!==FC.clock)fmDrawScene();
 return FC.shotFrame;
}
function fmShoot(){
 if(!FM_ACTIVE||FM_STATE!=='playing'||FM_PANEL||FC.coolUntil>FC.clock||FC.reloadUntil>FC.clock)return;
 const shot=fmShotSnapshot(),focus=shot?.focus||{ready:false,text:'Porta una persona nel mirino.'};
 if(!focus.ready||!focus.a){
  fmMessage(focus.text+'. Nessuno scatto perso.');
  fmUpdateHud(focus);
  return; // Composition is guidance, never a language mistake or combo loss.
 }
 FC.coolUntil=FC.clock+.5;
 FM.ammo=(FM.ammo??5)-1;
 const q=FM_ROUNDS[FM.index],success=focus.a.id===q.person;
 if(TR_SOUND_PREFS.visuals!==false&&!matchMedia('(prefers-reduced-motion:reduce)').matches)document.getElementById('fc-flash')?.animate([{opacity:.85},{opacity:0}],{duration:FM.relax?80:220});
 trChime('photo');
 if(success){
  const first=!FM.wrong[FM.index];
  if(first){FM.first++;FM.combo++}else FM.combo=0;
  FM.bestCombo=Math.max(FM.bestCombo,FM.combo);
  FM.score+=100+Math.round(focus.quality*.6)+(first?30:0)+Math.min(FM.combo,5)*10;
  FM.photos[FM.index]={id:q.person,word:q.word,quality:focus.quality,src:fmPhoto(shot)};
  FM.completed.push(FM.index);FM_STATE='capture';fmSave();fmRender();trFeedback();fmSpeakRound(true);
 }else{
  FM.wrong[FM.index]=(FM.wrong[FM.index]||0)+1;FM.combo=0;TR_REWARD.streak=0;trChime('wrong');
  fmMessage('Hai fotografato '+FC_PEOPLE[focus.a.id].n+'. Riascolta chi cercare.');
  if(FM.ammo<=0){FC.reloadUntil=FC.clock+1.15;fmMessage('Rullino finito: ne preparo uno nuovo…')}
  fmSave();fmUpdateHud(focus);
 }
}

/* The selected focus is a camera choice, never a hint to the language answer. */
Object.assign(FC,{focusId:null,manualId:null,alpha:[],outlines:new Map(),pinchUsed:false,shutterHandled:false,lastPress:-Infinity});
function fmCrop(){return {x:FC.w*.18,y:FC.h*.175,w:FC.w*.64,h:FC.h*.69}}
function fmActorBounds(a){const f=FC_ART.people[a.id].frames[a.frame],w=a.h*f.w/f.h;return {x:a.cx-w/2,y:a.ground-a.h,w,h:a.h}}
function fmClearFocus(){FC.focusId=FC.manualId=null;FC.shotFrame=null}
function fmBuildAlpha(){FC.alpha=FC.images.map((img,i)=>{if(!i)return null;const c=document.createElement('canvas');c.width=img.width;c.height=img.height;const ctx=c.getContext('2d',{willReadFrequently:true});ctx.drawImage(img,0,0);const rgba=ctx.getImageData(0,0,c.width,c.height).data,alpha=new Uint8Array(c.width*c.height);for(let k=0;k<alpha.length;k++)alpha[k]=rgba[k*4+3];const result={alpha,w:c.width,h:c.height};c.width=c.height=0;return result})}
function fmHitTest(x,y){const actors=fmProjectActors();for(let i=actors.length-1;i>=0;i--){const a=actors[i],b=fmActorBounds(a);if(x<b.x||x>b.x+b.w||y<b.y||y>b.y+b.h)continue;const s=FC_ART.people[a.id],f=s.frames[a.frame],atlas=FC.alpha[s.image];let u=(x-b.x)/b.w;if(a.dir<0)u=1-u;const sx=Math.floor(f.x+u*f.w),sy=Math.floor(f.y+(y-b.y)/b.h*f.h);if(atlas&&atlas.alpha[sy*atlas.w+sx]>65)return a.id}return null}
function fmSelectPerson(id){trJCameraSelect(id);FC.manualId=id;FC.focusId=id;fmDrawScene();fmUpdateHud();if(id)fmMessage('Fuoco fissato su '+FC_PEOPLE[id].n+'. Ora inquadra e scatta.');else fmMessage('Fuoco automatico: porta una persona nel mirino.')}
function fmPickAt(x,y){FC.manualId=fmHitTest(x,y);FC.focusId=FC.manualId;fmDrawScene();fmUpdateHud();if(FC.manualId)fmMessage('Fuoco fissato su '+FC_PEOPLE[FC.manualId].n+'. Ora inquadra e scatta.');else fmMessage('Fuoco automatico: porta una persona nel mirino.')}
function fmAutoFocus(){fmClearFocus();fmDrawScene();fmUpdateHud();fmMessage('Fuoco automatico: porta una persona nel mirino.')}

function fmOutline(a){const s=FC_ART.people[a.id],key=a.id+'|'+a.frame;let cached=FC.outlines.get(key);if(cached){FC.outlines.delete(key);FC.outlines.set(key,cached);return cached}const f=s.frames[a.frame],pad=10,mask=document.createElement('canvas');mask.width=f.w+pad*2;mask.height=f.h+pad*2;const m=mask.getContext('2d');m.drawImage(FC.images[s.image],f.x,f.y,f.w,f.h,pad,pad,f.w,f.h);const make=(color,radius)=>{const tint=document.createElement('canvas');tint.width=mask.width;tint.height=mask.height;const t=tint.getContext('2d');t.drawImage(mask,0,0);t.globalCompositeOperation='source-in';t.fillStyle=color;t.fillRect(0,0,tint.width,tint.height);const out=document.createElement('canvas');out.width=mask.width;out.height=mask.height;const c=out.getContext('2d');for(let i=0;i<16;i++){const angle=i*Math.PI/8;c.drawImage(tint,Math.cos(angle)*radius,Math.sin(angle)*radius)}c.globalCompositeOperation='destination-out';c.drawImage(mask,0,0);tint.width=tint.height=0;return out};cached={white:make('#fff',5),blue:make('#1f4e9c',3),pad};mask.width=mask.height=0;cached.bytes=(cached.white.width*cached.white.height+cached.blue.width*cached.blue.height)*4;FC.outlines.set(key,cached);let bytes=0;for(const o of FC.outlines.values())bytes+=o.bytes;while(FC.outlines.size>24||bytes>8*1024*1024){const key=FC.outlines.keys().next().value,old=FC.outlines.get(key);bytes-=old.bytes;FC.outlines.delete(key);old.white.width=old.white.height=old.blue.width=old.blue.height=0}return cached}
function fmDrawFocus(c,focus){if(!focus.a)return;const a=focus.a,f=FC_ART.people[a.id].frames[a.frame],o=fmOutline(a),b=fmActorBounds(a),scale=a.h/f.h;c.save();c.translate(a.cx,b.y);if(a.dir<0)c.scale(-1,1);const x=-b.w/2-o.pad*scale,y=-o.pad*scale,w=o.white.width*scale,h=o.white.height*scale;c.drawImage(o.white,x,y,w,h);c.drawImage(o.blue,x,y,w,h);c.restore()}
function fmPointerDown(e){if(FM_STATE!=='playing'||FM_PANEL)return;FC.rect=e.currentTarget.getBoundingClientRect();FC.touches.set(e.pointerId,{x:e.clientX,y:e.clientY});e.currentTarget.setPointerCapture(e.pointerId);if(FC.touches.size===1){FC.pinchUsed=false;FC.drag={id:e.pointerId,x:e.clientX,y:e.clientY,px:FC.panX,py:FC.panY,moved:false,hit:fmHitTest(e.clientX-FC.rect.left,e.clientY-FC.rect.top)}}else if(FC.touches.size===2){FC.pinchUsed=true;const[a,b]=[...FC.touches.values()];FC.pinch={distance:Math.hypot(a.x-b.x,a.y-b.y),zoom:FC.zoom}}}
function fmPointerMove(e){if(!FC.touches.has(e.pointerId)||FM_PANEL)return;FC.touches.set(e.pointerId,{x:e.clientX,y:e.clientY});if(FC.touches.size===2&&FC.pinch){const[a,b]=[...FC.touches.values()];fmSetZoom(FC.pinch.zoom*Math.hypot(a.x-b.x,a.y-b.y)/Math.max(20,FC.pinch.distance))}else if(FC.drag){if(Math.hypot(e.clientX-FC.drag.x,e.clientY-FC.drag.y)>8)FC.drag.moved=true;FC.panX=fcClamp(FC.drag.px+(e.clientX-FC.drag.x)/FC.w,-FC_MOTION.panX,FC_MOTION.panX);FC.panY=fcClamp(FC.drag.py+(e.clientY-FC.drag.y)/FC.h,-FC_MOTION.panY,FC_MOTION.panY);fmRequestDraw()}}
function fmPointerUp(e){const tap=FC.drag&&!FC.drag.moved&&!FC.pinchUsed&&FC.touches.size===1&&e.type!=='pointercancel';if(tap)fmSelectPerson(FC.drag.hit);FC.touches.delete(e.pointerId);try{e.currentTarget.releasePointerCapture(e.pointerId)}catch(err){}FC.pinch=null;if(FC.touches.size===1){const[id,p]=[...FC.touches][0];FC.drag={id,x:p.x,y:p.y,px:FC.panX,py:FC.panY,moved:true}}else FC.drag=null}
function fmPressShutter(e){if(e.button!==0||!e.isPrimary)return;e.preventDefault();FC.shutterHandled=true;fmShoot()}
function fmShutterClick(e){if(e.detail===0){FC.shutterHandled=false;fmShoot();return}if(FC.shutterHandled){FC.shutterHandled=false;return}fmShoot()}

/* v1.5: separate character casting, deliberately articulated alphabet recordings,
   and short, non-blocking rewards. All voice recordings are embedded below. */
const TR_REWARD={streak:0,sequence:0,nodes:new Set(),timer:0,visualTimer:0,level:0};
/* Satisfaction is event-driven and never owns game input or progression. */
Object.assign(TR_REWARD,{bags:{},recent:[],pending:null,active:null,lastVoiceId:null,eventId:0,lastVoiceEnd:-Infinity,visualAt:-Infinity,visualTier:-1,visualTimer:0,history:[]});
function trResetStreak(){TR_REWARD.streak=0;if(TR_REWARD.pending&&!TR_REWARD.pending.event.major){TR_REWARD.sequence++;TR_REWARD.pending=null;clearTimeout(TR_SOUND.feedbackTimer)}if(TR_REWARD.active&&!TR_REWARD.active.major)trStopReactionPlayback();trClearRewardVisual()}
function trRewardPool(kind,n){return kind==='combo'?(n===3?'combo3':n===5?'combo5':n===8?'combo8':n===12?'combo12':'comboHigh'):kind}
function trRewardPick(pool){const phrases=TR_NEURAL_PACK.reactions[pool]||TR_NEURAL_PACK.reactions.success;let bag=TR_REWARD.bags[pool];if(!bag?.length){bag=phrases.slice();for(let i=bag.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[bag[i],bag[j]]=[bag[j],bag[i]]}TR_REWARD.bags[pool]=bag}let index=bag.findIndex(t=>!TR_REWARD.recent.includes(t));if(index<0)index=0;const text=bag.splice(index,1)[0];TR_REWARD.recent.push(text);if(TR_REWARD.recent.length>6)TR_REWARD.recent.shift();return text}
function trRewardEvent(kind){const n=TR_REWARD.streak,major=['level','perfect','recover'].includes(kind),tier=major?4:kind==='combo'?(n>=12?4:n>=8?3:n>=5?2:1):0,pool=trRewardPool(kind,n),text=trRewardPick(pool),idx=TR_SOUND.praiseIndex++,gender=TR_REWARD.lastVoiceId==='it-isabella'?'male':'female';const headline=kind==='perfect'?'TUTTO GIUSTO!':kind==='level'?'LIVELLO COMPLETATO!':kind==='recover'?'CE L’HAI FATTA!':kind==='combo'?(n===3?'TRIPLA!':n===5?'MITICO!':n===8?'INCREDIBILE!':n===12?'STRAORDINARIO!':'CHE SERIE!'):text.split(/[.!?]/)[0]+'!';return{id:++TR_REWARD.eventId,kind,pool,text,headline,streak:n,tier,major,voice:trCastId('it-IT',gender),created:performance.now(),priority:major?10:tier}}
