    const choices=list.filter(v=>trNormLang(v.lang)===trNormLang(lang)).sort((a,b)=>trVoiceScore(b,lang)-trVoiceScore(a,lang)),pref=TR_PREFS[role+'Voice'];const opts=[['','Voce guida · automatica']];
