const TR_WORLD_DESIGN=Object.freeze({version:'1.10.5',surface:'course map and recurring companions',mode:'operate',direction:'Russian painted-wood travel diorama; red/cobalt/ivory identity; tactile raised lesson medallions, four original miniature landmarks, expressive lacquered doll and scarfed brown bear',firstViewport:'A single bottom-to-top route contains every world and course group. Open at the current node; keep navigation and a recenter control reachable while scrolling. Four blended color zones and embedded landmarks identify worlds inside the same scene.',signature:'Current lesson is marked by a breathing ring and curious matryoshka; its medallion touch target stays stationary. World boundaries never filter or replace the map; the continuous road rises through all four zones. Keep original progression and place names.',constraints:['single distributable HTML','all 281 original stages and existing save keys','phone-first 44px targets','offline artwork and approved recordings','no blocking celebrations','reduced motion and independent visual mute'],tokens:{cream:'#f7f3e9',cobalt:'#1f4e9c',red:'#c8323c',ink:'#14224a',muted:'#51608c'},artPaletteGuidance:['muted pine green','restrained gold'],atlas:{mascots:[3,2],landmarks:[2,2]}});
