const TR_COMPANION={timer:0,lastMistake:-Infinity,mistakes:0,observer:null};
const TR_CHAPTERS=[{name:'Alfabeto',place:'La scuola delle lettere',copy:'Riconosci i segni, scopri i suoni.',landmark:0},{name:'Lessico',place:'Le parole del villaggio',copy:'Persone, oggetti e piccole scoperte.',landmark:1},{name:'Genere',place:'Le tre case del genere',copy:'Maschile, femminile e neutro.',landmark:2},{name:'Frasi',place:'Due chiacchiere al samovar',copy:'Le parole cominciano a stare insieme.',landmark:3}];
function trMascot(character,expression=0,extra=''){return '<span class="tr-mascot '+extra+'" data-character="'+character+'" data-expression="'+expression+'" style="--sprite-x:'+((expression%3)*50)+'%;--sprite-y:'+(expression>=3?100:0)+'%" aria-hidden="true"></span>'}
function trMascotMood(el,character,expression){if(!el)return;el.dataset.character=character;el.dataset.expression=String(expression);el.style.setProperty('--sprite-x',(expression%3)*50+'%');el.style.setProperty('--sprite-y',(expression>=3?100:0)+'%')}
function trLandmark(index,extra=''){return '<span class="tr-landmark '+extra+'" data-landmark="'+index+'" style="--landmark-x:'+(index%2?100:0)+'%;--landmark-y:'+(index>=2?100:0)+'%" aria-hidden="true"></span>'}
function trMapLabel(g){return nm(g).replace('Tracciamento · ','Traccia: ').replace('Saluti e formule di cortesia','Saluti e cortesia').replace(/ · insieme /,' · ')}
/* CONTINUOUS MAP v1.10.3 — product invariant: all four worlds share ONE route.
   Course order rises from bottom to top. World changes are scenery/color changes,
   never tabs or filtered pages. Group indexes, stage IDs, locks and save keys
   remain the course's own. A scroll event schedules at most one small RAF.
   Do not animate or promote the entire tall route to a composited layer. */
function trMapLeave(){cancelAnimationFrame(TR_MAP.scrollFrame);cancelAnimationFrame(TR_MAP.frame);TR_MAP.scrollFrame=TR_MAP.frame=0;TR_MAP.worlds=[];TR_MAP.color=null;document.body.style.removeProperty('background-color');document.getElementById('tr-topbar')?.style.removeProperty('background-color')}
function trMapSchedule(){if(!TR_MAP.worlds.length||TR_MAP.scrollFrame)return;TR_MAP.scrollFrame=requestAnimationFrame(()=>{TR_MAP.scrollFrame=0;trMapTrack()})}
/* Do not update inherited CSS variables while scrolling: the embedded artwork
   uses large data URLs in CSS variables, making that trigger costly style work.
   Non-inherited background colors and visible-only transforms avoid the cascade. */
function trMapTint(){const color=getComputedStyle(document.body).getPropertyValue('--tr-world-'+TR_MAP.chapter).trim();if(!color||TR_MAP.color===color)return;TR_MAP.color=color;for(const el of [document.body,document.getElementById('tr-topbar'),document.querySelector('.tr-map-position')])if(el)el.style.backgroundColor=color}
function trMapTrack(){const route=document.querySelector('.tr-map-route');if(!route||app.hidden||!TR_MAP.worlds.length)return;const y=innerHeight*.48-route.getBoundingClientRect().top,world=TR_MAP.worlds.find(w=>y>=w.top&&y<w.bottom)||TR_MAP.worlds[y<0?3:0],label=document.getElementById('tr-map-world-label');if(label&&label.dataset.world!==String(world.lv)){label.dataset.world=world.lv;label.textContent='Mondo '+world.lv+' · '+TR_CHAPTERS[world.lv-1].name}TR_MAP.chapter=world.lv;trMapTint()}
function trMapLean(e){if(!matchMedia('(hover:hover)').matches||!TR_MAP.worlds.length||TR_SOUND_PREFS.visuals===false||matchMedia('(prefers-reduced-motion:reduce)').matches)return;const lean=((e.clientX/innerWidth-.5)*5).toFixed(2);cancelAnimationFrame(TR_MAP.frame);TR_MAP.frame=requestAnimationFrame(()=>{TR_MAP.frame=0;for(const el of document.querySelectorAll('.tr-map-route .tr-route-landmark')){const r=el.getBoundingClientRect();if(r.bottom>0&&r.top<innerHeight)el.style.transform='perspective(700px) rotateY('+lean+'deg)'}})}
function trMapCurrent(){trMapScroll(document.getElementById('cur')||document.querySelector('.tr-map-stop:last-of-type'),'smooth')}
function trMapScroll(el,behavior='instant'){if(!el)return;const quiet=matchMedia('(prefers-reduced-motion:reduce)').matches||TR_SOUND_PREFS.visuals===false;el.scrollIntoView({block:'center',behavior:quiet?'instant':behavior});trMapSchedule()}
function trMapChapter(lv){if(!Number.isInteger(lv)||lv<1||lv>4)return;if(!app.querySelector('.tr-map-route')){home({chapter:lv});return}trMapScroll(document.getElementById('tr-world-'+lv),'smooth')}
