function trMapAnchor(){let best=null;const center=innerHeight*.5;for(const el of app.querySelectorAll('.tr-map-stop')){const y=el.getBoundingClientRect().top,d=Math.abs(y-center);if(!best||d<best.distance)best={key:el.dataset.mapKey,y,distance:d}}return best}
