 const gates=worlds.map(w=>{const c=TR_CHAPTERS[w.lv-1],total=w.groups.reduce((n,o)=>n+o.g.st.length,0),completed=w.groups.reduce((n,o)=>n+gst(o.g).n,0);return '<section class="tr-world-gate" id="tr-world-'+w.lv+'" data-world="'+w.lv+'" aria-labelledby="tr-world-title-'+w.lv+'" style="top:'+(height-w.gate-176)+'px"><div><h2 id="tr-world-title-'+w.lv+'">'+w.lv+' · '+c.name+'</h2><p>'+c.place+'</p><span class="tr-map-chapter-count">'+completed+' di '+total+' tappe</span><progress value="'+completed+'" max="'+total+'" aria-label="Avanzamento mondo '+c.name+'"></progress></div>'+trLandmark(c.landmark,'tr-chapter-landmark')+'</section>'}).join('');
