function trMountMascots(){document.querySelectorAll('svg:has(> use[href="#m"])').forEach(svg=>{if(svg.closest('defs')||svg.querySelector('defs,symbol'))return;const span=document.createElement('span');span.className='tr-mascot '+(svg.getAttribute('class')||'');if(svg.id)span.id=svg.id;span.setAttribute('aria-hidden','true');const expression=span.id==='dl'&&app.querySelector('#sl')?[0,4,5,2][ii]||0:0;trMascotMood(span,'matryoshka',expression);svg.replaceWith(span)});const d=document.getElementById('dl');if(d&&!d.classList.contains('on')&&d.dataset.expression==='1')trMascotMood(d,'matryoshka',app.querySelector('#sl')?[0,4,5,2][ii]||0:0)}
