function trShowCompanion(character,expression,text,kind='mistake'){if(TR_SOUND_PREFS.visuals===false||document.hidden||app.hidden||app.querySelector('.tr-start')||document.getElementById('tr-pause')?.open)return;trClearCompanion();const box=document.createElement('div');box.id='tr-companion-feedback';box.className='tr-companion-feedback '+kind;box.setAttribute('role','status');box.innerHTML=trMascot(character,expression)+'<span>'+trEscape(text)+'</span>';if(typeof FM_ACTIVE!=='undefined'&&FM_ACTIVE){const target=document.querySelector('.fc-target');if(target){const rect=target.getBoundingClientRect();box.classList.add('in-camera');box.style.left=(rect.right-82)+'px';box.style.top=(rect.top-6)+'px'}}document.body.append(box);TR_COMPANION.timer=setTimeout(()=>box.remove(),kind==='mistake'?1900:2400)}
